    "空白处有人算过一笔账，划掉重写，最后留了两个字：不值。",
    "有人画了一株稻子，画得歪歪扭扭，穗子画得特别大。",
    "页边写着：老师说插秧前要晒三天。我爸说看天。那年我信了书，赔了半亩。",
